import json
import sys

import torch
import ttl
import ttnn

assert ttnn.__name__ == "ttl.sim.ttnnsim", ttnn.__name__
assert not any("site-packages/ttnn" in str(getattr(m, "__file__", "")) for m in sys.modules.values())


@ttl.operation(grid=(1, 1))
def add(a, b, y):
    aa = ttl.make_dataflow_buffer_like(a, shape=(1, 1), block_count=2)
    bb = ttl.make_dataflow_buffer_like(b, shape=(1, 1), block_count=2)
    yy = ttl.make_dataflow_buffer_like(y, shape=(1, 1), block_count=2)

    @ttl.datamovement()
    def read():
        with aa.reserve() as av, bb.reserve() as bv:
            ttl.copy(a[0, 0], av).wait()
            ttl.copy(b[0, 0], bv).wait()

    @ttl.compute()
    def compute():
        with aa.wait() as av, bb.wait() as bv, yy.reserve() as yv:
            yv.store(av + bv)

    @ttl.datamovement()
    def write():
        with yy.wait() as yv:
            ttl.copy(yv, y[0, 0]).wait()


@ttl.operation(grid=(1, 1))
def matmul(a, b, y):
    aa = ttl.make_dataflow_buffer_like(a, shape=(1, 1), block_count=2)
    bb = ttl.make_dataflow_buffer_like(b, shape=(1, 1), block_count=2)
    yy = ttl.make_dataflow_buffer_like(y, shape=(1, 1), block_count=2)

    @ttl.datamovement()
    def read():
        with aa.reserve() as av, bb.reserve() as bv:
            ttl.copy(a[0, 0], av).wait()
            ttl.copy(b[0, 0], bv).wait()

    @ttl.compute()
    def compute():
        with aa.wait() as av, bb.wait() as bv, yy.reserve() as yv:
            yv.store(av @ bv)

    @ttl.datamovement()
    def write():
        with yy.wait() as yv:
            ttl.copy(yv, y[0, 0]).wait()


device = ttnn.open_device(device_id=0)
try:
    a = torch.arange(1024, dtype=torch.float32).reshape(32, 32) % 7
    b = (torch.arange(1024, dtype=torch.float32).reshape(32, 32) % 5) - 2

    def upload(value):
        return ttnn.from_torch(value, dtype=ttnn.float32, layout=ttnn.TILE_LAYOUT,
                               device=device, memory_config=ttnn.DRAM_MEMORY_CONFIG)

    ta, tb = upload(a), upload(b)
    results = {}
    for name, operation, expected in (("add", add, a + b), ("matmul", matmul, a @ b)):
        y = upload(torch.zeros_like(a))
        operation(ta, tb, y)
        actual = ttnn.to_torch(y)
        torch.testing.assert_close(actual, expected, rtol=0, atol=0)
        results[name] = {"max_abs_error": (actual - expected).abs().max().item(), "shape": list(actual.shape)}
    print(json.dumps({"evidence": "upstream-tt-lang-sim-not-hardware", "results": results}))
finally:
    ttnn.close_device(device)
